-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.report_resolutions (
  id uuid default gen_random_uuid() not null,
  target_kind text not null,
  target_id text not null,
  status text not null,
  public_note text,
  fixed_version integer,
  resolved_at timestamp with time zone default now() not null,
  constraint report_resolutions_pkey PRIMARY KEY (id),
  constraint report_resolutions_fixed_version_check CHECK (((fixed_version >= 1) AND (fixed_version <= 100000))),
  constraint report_resolutions_public_note_check CHECK ((char_length(public_note) <= 500)),
  constraint report_resolutions_status_check CHECK ((status = ANY (ARRAY['fixed'::text, 'not_an_error'::text, 'wont_fix'::text]))),
  constraint report_resolutions_target_id_check CHECK (((char_length(target_id) >= 1) AND (char_length(target_id) <= 200)))
);

CREATE INDEX report_resolutions_resolved ON public.report_resolutions USING btree (resolved_at);
CREATE INDEX report_resolutions_target ON public.report_resolutions USING btree (target_kind, target_id);

alter table public.report_resolutions enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.report_resolutions to service_role;
